    public func updateTextStyle(id: String, content: String? = nil, fontFamily: String? = nil, fontSize: UInt32? = nil, bold: Bool? = nil, italic: Bool? = nil, textAlign: String? = nil, verticalAlign: String? = nil, updatedAt: UInt64) async throws {
        let args = try JSONEncoder().encode(UpdateTextStyleArgs(id: id, content: content, fontFamily: fontFamily, fontSize: fontSize, bold: bold, italic: italic, textAlign: textAlign, verticalAlign: verticalAlign, updatedAt: updatedAt))
        _ = try await transport.execute(method: "update_text_style", argsJSON: args)
    }

